namespace sv_9ea731fcb82c44b481bbd613e8db4b09.Models;

public record JobApplication(PersonalInfo Personal, WorkHistory Work, List<Reference> References, string CoverLetter);
public record PersonalInfo(string FullName, string Email, string Phone, string Address);
public record WorkHistory(List<WorkEntry> Entries);
public record WorkEntry(string Company, string Title, DateTime StartDate, DateTime? EndDate, string Description);
public record Reference(string Name, string Relationship, string Email, string Phone);

public interface IApplicationService
{
    Task<int> SubmitApplicationAsync(JobApplication application);
    Task<bool> ValidateEmailAsync(string email);
}

using sv_9ea731fcb82c44b481bbd613e8db4b09.Models;

namespace sv_9ea731fcb82c44b481bbd613e8db4b09.Services;

public class ApplicationService : IApplicationService
{
    public async Task<int> SubmitApplicationAsync(JobApplication application)
    {
        await Task.Delay(1000);
        return Random.Shared.Next(10000, 99999);
    }

    public async Task<bool> ValidateEmailAsync(string email)
    {
        await Task.Delay(300);
        return !string.IsNullOrWhiteSpace(email)
            && email.Contains('@')
            && email.Contains('.');
    }
}

namespace sv_9ea731fcb82c44b481bbd613e8db4b09.Models;

public class PersonalInfoModel
{
    public string FullName { get; set; } = "";
    public string Email { get; set; } = "";
    public string Phone { get; set; } = "";
    public string Address { get; set; } = "";
}

public class WorkEntryModel
{
    public string Company { get; set; } = "";
    public string Title { get; set; } = "";
    public DateTime? StartDate { get; set; }
    public DateTime? EndDate { get; set; }
    public bool IsCurrent { get; set; }
    public string Description { get; set; } = "";
}

public class ReferenceModel
{
    public string Name { get; set; } = "";
    public string Relationship { get; set; } = "";
    public string Email { get; set; } = "";
    public string Phone { get; set; } = "";
}

@namespace sv_9ea731fcb82c44b481bbd613e8db4b09.Components.JobApplication

<div class="step-indicator d-flex justify-content-between mb-4">
    @for (int i = 0; i < StepNames.Count; i++)
    {
        var step = i;
        var isCompleted = CompletedSteps.Contains(step);
        var isCurrent = step == CurrentStep;
        var isFuture = !isCompleted && !isCurrent;
        var clickable = isCompleted;

        <div class="step-item text-center flex-fill @(isCurrent ? "active" : "") @(isCompleted ? "completed" : "") @(isFuture ? "future" : "")"
             @onclick="() => HandleClick(step)"
             role="@(clickable ? "button" : "")">
            <div class="step-circle mx-auto mb-1 @(isCurrent ? "bg-primary text-white border-primary" : isCompleted ? "bg-success text-white border-success" : "bg-light text-muted")">
                @if (isCompleted)
                {
                    <span>✓</span>
                }
                else
                {
                    <span>@(step + 1)</span>
                }
            </div>
            <small class="step-label @(isFuture ? "text-muted" : isCurrent ? "fw-bold text-primary" : "text-success")">
                @StepNames[step]
            </small>
        </div>
    }
</div>

@code {
    [Parameter] public int CurrentStep { get; set; }
    [Parameter] public HashSet<int> CompletedSteps { get; set; } = new();
    [Parameter] public List<string> StepNames { get; set; } = new();
    [Parameter] public EventCallback<int> OnStepClicked { get; set; }

    private async Task HandleClick(int step)
    {
        if (CompletedSteps.Contains(step))
        {
            await OnStepClicked.InvokeAsync(step);
        }
    }
}

.step-indicator {
    position: relative;
}

.step-circle {
    width: 38px;
    height: 38px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: bold;
    border: 2px solid #dee2e6;
    transition: all 0.2s ease;
}

.step-item.completed {
    cursor: pointer;
}

.step-item.completed:hover .step-circle {
    transform: scale(1.1);
}

.step-item.future {
    opacity: 0.5;
}

.step-label {
    font-size: 0.8rem;
}

@namespace sv_9ea731fcb82c44b481bbd613e8db4b09.Components.JobApplication
@using sv_9ea731fcb82c44b481bbd613e8db4b09.Models

<div class="card mb-3">
    <div class="card-body">
        <div class="d-flex justify-content-between align-items-center mb-3">
            <h6 class="card-title mb-0">Reference @(Index + 1)</h6>
            @if (CanRemove)
            {
                <button class="btn btn-outline-danger btn-sm" @onclick="OnRemove">Remove</button>
            }
        </div>

        <div class="row mb-2">
            <div class="col-md-6">
                <label class="form-label">Name <span class="text-danger">*</span></label>
                <input type="text" class="form-control" @bind="Reference.Name" @bind:event="oninput" />
            </div>
            <div class="col-md-6">
                <label class="form-label">Relationship <span class="text-danger">*</span></label>
                <input type="text" class="form-control" @bind="Reference.Relationship" @bind:event="oninput" />
            </div>
        </div>

        <div class="row mb-0">
            <div class="col-md-6">
                <label class="form-label">Email <span class="text-danger">*</span></label>
                <input type="email" class="form-control" @bind="Reference.Email" @bind:event="oninput" />
            </div>
            <div class="col-md-6">
                <label class="form-label">Phone <span class="text-danger">*</span></label>
                <input type="tel" class="form-control" @bind="Reference.Phone" @bind:event="oninput" />
            </div>
        </div>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public ReferenceModel Reference { get; set; } = default!;
    [Parameter] public int Index { get; set; }
    [Parameter] public bool CanRemove { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }
}

@namespace sv_9ea731fcb82c44b481bbd613e8db4b09.Components.JobApplication
@using sv_9ea731fcb82c44b481bbd613e8db4b09.Models

<h4 class="mb-3">Personal Information</h4>

<div class="mb-3">
    <label class="form-label">Full Name <span class="text-danger">*</span></label>
    <input type="text" class="form-control @ValidationClass("FullName")"
           @bind="Model.FullName" @bind:event="oninput" />
    @if (errors.ContainsKey("FullName"))
    {
        <div class="invalid-feedback">@errors["FullName"]</div>
    }
</div>

<div class="mb-3">
    <label class="form-label">Email <span class="text-danger">*</span></label>
    <input type="email" class="form-control @ValidationClass("Email")"
           @bind="Model.Email" @bind:event="oninput" />
    @if (errors.ContainsKey("Email"))
    {
        <div class="invalid-feedback">@errors["Email"]</div>
    }
</div>

<div class="mb-3">
    <label class="form-label">Phone <span class="text-danger">*</span></label>
    <input type="tel" class="form-control @ValidationClass("Phone")"
           @bind="Model.Phone" @bind:event="oninput" />
    @if (errors.ContainsKey("Phone"))
    {
        <div class="invalid-feedback">@errors["Phone"]</div>
    }
</div>

<div class="mb-3">
    <label class="form-label">Address <span class="text-danger">*</span></label>
    <textarea class="form-control @ValidationClass("Address")"
              @bind="Model.Address" @bind:event="oninput" rows="2"></textarea>
    @if (errors.ContainsKey("Address"))
    {
        <div class="invalid-feedback">@errors["Address"]</div>
    }
</div>

@if (isValidating)
{
    <div class="text-info mb-3">
        <span class="spinner-border spinner-border-sm"></span> Validating email…
    </div>
}

<div class="d-flex justify-content-end">
    <button class="btn btn-primary" @onclick="HandleNext" disabled="@isValidating">Next →</button>
</div>

@code {
    [Parameter, EditorRequired] public PersonalInfoModel Model { get; set; } = default!;
    [Parameter, EditorRequired] public IApplicationService ApplicationService { get; set; } = default!;
    [Parameter] public EventCallback OnNext { get; set; }

    private Dictionary<string, string> errors = new();
    private bool isValidating;

    private string ValidationClass(string field) =>
        errors.ContainsKey(field) ? "is-invalid" : "";

    private async Task HandleNext()
    {
        errors.Clear();

        if (string.IsNullOrWhiteSpace(Model.FullName))
            errors["FullName"] = "Full name is required.";
        if (string.IsNullOrWhiteSpace(Model.Email))
            errors["Email"] = "Email is required.";
        if (string.IsNullOrWhiteSpace(Model.Phone))
            errors["Phone"] = "Phone number is required.";
        if (string.IsNullOrWhiteSpace(Model.Address))
            errors["Address"] = "Address is required.";

        if (errors.Count > 0) return;

        isValidating = true;
        var isValidEmail = await ApplicationService.ValidateEmailAsync(Model.Email);
        isValidating = false;

        if (!isValidEmail)
        {
            errors["Email"] = "Please enter a valid email address.";
            return;
        }

        await OnNext.InvokeAsync();
    }
}

@namespace sv_9ea731fcb82c44b481bbd613e8db4b09.Components.JobApplication
@using sv_9ea731fcb82c44b481bbd613e8db4b09.Models

<h4 class="mb-3">Work History</h4>

@for (int i = 0; i < Entries.Count; i++)
{
    var index = i;
    <WorkEntryForm Entry="Entries[index]" Index="index"
                   CanRemove="Entries.Count > 1"
                   OnRemove="() => RemoveEntry(index)" />
}

<button class="btn btn-outline-secondary mb-3" @onclick="AddEntry">
    + Add Another Position
</button>

@if (!string.IsNullOrEmpty(error))
{
    <div class="alert alert-danger">@error</div>
}

<div class="d-flex justify-content-between">
    <button class="btn btn-secondary" @onclick="OnBack">← Back</button>
    <button class="btn btn-primary" @onclick="HandleNext">Next →</button>
</div>

@code {
    [Parameter, EditorRequired] public List<WorkEntryModel> Entries { get; set; } = default!;
    [Parameter] public EventCallback OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private string? error;

    private void AddEntry()
    {
        Entries.Add(new WorkEntryModel());
    }

    private void RemoveEntry(int index)
    {
        if (Entries.Count > 1)
            Entries.RemoveAt(index);
    }

    private async Task HandleNext()
    {
        error = null;

        foreach (var entry in Entries)
        {
            if (string.IsNullOrWhiteSpace(entry.Company)
                || string.IsNullOrWhiteSpace(entry.Title)
                || entry.StartDate is null)
            {
                error = "Each position requires a company name, job title, and start date.";
                return;
            }
        }

        await OnNext.InvokeAsync();
    }
}

@namespace sv_9ea731fcb82c44b481bbd613e8db4b09.Components.JobApplication
@using sv_9ea731fcb82c44b481bbd613e8db4b09.Models

<h4 class="mb-3">References</h4>
<p class="text-muted">Please provide 2–3 professional references.</p>

@for (int i = 0; i < References.Count; i++)
{
    var index = i;
    <ReferenceForm Reference="References[index]" Index="index"
                   CanRemove="References.Count > 1"
                   OnRemove="() => RemoveReference(index)" />
}

@if (References.Count < 3)
{
    <button class="btn btn-outline-secondary mb-3" @onclick="AddReference">
        + Add Reference
    </button>
}

@if (!string.IsNullOrEmpty(error))
{
    <div class="alert alert-danger">@error</div>
}

<div class="d-flex justify-content-between">
    <button class="btn btn-secondary" @onclick="OnBack">← Back</button>
    <button class="btn btn-primary" @onclick="HandleNext">Next →</button>
</div>

@code {
    [Parameter, EditorRequired] public List<ReferenceModel> References { get; set; } = default!;
    [Parameter] public EventCallback OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private string? error;

    private void AddReference()
    {
        if (References.Count < 3)
            References.Add(new ReferenceModel());
    }

    private void RemoveReference(int index)
    {
        if (References.Count > 1)
            References.RemoveAt(index);
    }

    private async Task HandleNext()
    {
        error = null;

        foreach (var r in References)
        {
            if (string.IsNullOrWhiteSpace(r.Name)
                || string.IsNullOrWhiteSpace(r.Relationship)
                || string.IsNullOrWhiteSpace(r.Email)
                || string.IsNullOrWhiteSpace(r.Phone))
            {
                error = "All fields are required for each reference.";
                return;
            }
        }

        await OnNext.InvokeAsync();
    }
}

@namespace sv_9ea731fcb82c44b481bbd613e8db4b09.Components.JobApplication

<h4 class="mb-3">Cover Letter</h4>

<div class="mb-3">
    <textarea class="form-control" rows="10" maxlength="@MaxLength"
              value="@text" @oninput="HandleInput"
              placeholder="Write your cover letter here…"></textarea>
    <div class="form-text text-end">
        @text.Length / @MaxLength characters
    </div>
</div>

<div class="d-flex justify-content-between">
    <button class="btn btn-secondary" @onclick="OnBack">← Back</button>
    <button class="btn btn-primary" @onclick="HandleNext">Next →</button>
</div>

@code {
    [Parameter] public string Text { get; set; } = "";
    [Parameter] public EventCallback<string> TextChanged { get; set; }
    [Parameter] public EventCallback OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private const int MaxLength = 2000;
    private string text = "";

    protected override void OnInitialized()
    {
        text = Text ?? "";
    }

    private async Task HandleInput(ChangeEventArgs e)
    {
        text = e.Value?.ToString() ?? "";
        if (text.Length > MaxLength)
            text = text[..MaxLength];
        await TextChanged.InvokeAsync(text);
    }

    private async Task HandleNext()
    {
        await TextChanged.InvokeAsync(text);
        await OnNext.InvokeAsync();
    }
}

@namespace sv_9ea731fcb82c44b481bbd613e8db4b09.Components.JobApplication
@using sv_9ea731fcb82c44b481bbd613e8db4b09.Models

<h4 class="mb-3">Review &amp; Submit</h4>

@* Personal Info *@
<div class="card mb-3">
    <div class="card-header d-flex justify-content-between align-items-center">
        <strong>Personal Information</strong>
        <a href="" @onclick="() => OnEditStep.InvokeAsync(0)" @onclick:preventDefault>Edit</a>
    </div>
    <div class="card-body">
        <p><strong>Name:</strong> @Personal.FullName</p>
        <p><strong>Email:</strong> @Personal.Email</p>
        <p><strong>Phone:</strong> @Personal.Phone</p>
        <p class="mb-0"><strong>Address:</strong> @Personal.Address</p>
    </div>
</div>

@* Work History *@
<div class="card mb-3">
    <div class="card-header d-flex justify-content-between align-items-center">
        <strong>Work History</strong>
        <a href="" @onclick="() => OnEditStep.InvokeAsync(1)" @onclick:preventDefault>Edit</a>
    </div>
    <div class="card-body">
        @foreach (var entry in WorkEntries)
        {
            <div class="mb-3 pb-2 border-bottom last-child-no-border">
                <p class="fw-bold mb-1">@entry.Title at @entry.Company</p>
                <p class="text-muted mb-1">
                    @entry.StartDate?.ToString("MMM yyyy") –
                    @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy") ?? "N/A")
                </p>
                @if (!string.IsNullOrWhiteSpace(entry.Description))
                {
                    <p class="mb-0">@entry.Description</p>
                }
            </div>
        }
    </div>
</div>

@* References *@
<div class="card mb-3">
    <div class="card-header d-flex justify-content-between align-items-center">
        <strong>References</strong>
        <a href="" @onclick="() => OnEditStep.InvokeAsync(2)" @onclick:preventDefault>Edit</a>
    </div>
    <div class="card-body">
        @foreach (var r in References)
        {
            <div class="mb-2">
                <strong>@r.Name</strong> — @r.Relationship<br />
                <span class="text-muted">@r.Email · @r.Phone</span>
            </div>
        }
    </div>
</div>

@* Cover Letter *@
<div class="card mb-3">
    <div class="card-header d-flex justify-content-between align-items-center">
        <strong>Cover Letter</strong>
        <a href="" @onclick="() => OnEditStep.InvokeAsync(3)" @onclick:preventDefault>Edit</a>
    </div>
    <div class="card-body">
        <p class="mb-0" style="white-space: pre-wrap;">@(string.IsNullOrWhiteSpace(CoverLetter) ? "(none)" : CoverLetter)</p>
    </div>
</div>

<div class="d-flex justify-content-between">
    <button class="btn btn-secondary" @onclick="OnBack">← Back</button>
    <button class="btn btn-success btn-lg" @onclick="HandleSubmit" disabled="@IsSubmitting">
        @if (IsSubmitting)
        {
            <span class="spinner-border spinner-border-sm me-1"></span>
            <span>Submitting…</span>
        }
        else
        {
            <span>Submit Application</span>
        }
    </button>
</div>

@code {
    [Parameter, EditorRequired] public PersonalInfoModel Personal { get; set; } = default!;
    [Parameter, EditorRequired] public List<WorkEntryModel> WorkEntries { get; set; } = default!;
    [Parameter, EditorRequired] public List<ReferenceModel> References { get; set; } = default!;
    [Parameter] public string CoverLetter { get; set; } = "";
    [Parameter] public bool IsSubmitting { get; set; }
    [Parameter] public EventCallback<int> OnEditStep { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }
    [Parameter] public EventCallback OnSubmit { get; set; }

    private async Task HandleSubmit()
    {
        await OnSubmit.InvokeAsync();
    }
}

@page "/apply"
@using sv_9ea731fcb82c44b481bbd613e8db4b09.Components.JobApplication
@using sv_9ea731fcb82c44b481bbd613e8db4b09.Models
@rendermode InteractiveServer
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="container py-4" style="max-width: 800px;">
    <h2 class="mb-4">Job Application</h2>

    @if (isSubmitted)
    {
        <div class="alert alert-success text-center py-5">
