{"path": "/tmp/sv-9ea731fcb82c44b481bbd613e8db4b09/Components/JobApplication/StepIndicator.razor", "file_text": "@namespace sv_9ea731fcb82c44b481bbd613e8db4b09.Components.JobApplication

<div class="step-indicator d-flex justify-content-between mb-4">
    @for (int i = 0; i < StepNames.Count; i++)
    {
        var step = i;
        var isCompleted = CompletedSteps.Contains(step);
        var isCurrent = step == CurrentStep;
        var isFuture = !isCompleted && !isCurrent;
        var clickable = isCompleted;

        <div class="step-item text-center flex-fill @(isCurrent ? "active" : "") @(isCompleted ? "completed" : "") @(isFuture ? "future" : "")"
             @onclick="() => HandleClick(step)"
             role="@(clickable ? "button" : "")">
            <div class="step-circle mx-auto mb-1 @(isCurrent ? "bg-primary text-white border-primary" : isCompleted ? "bg-success text-white border-success" : "bg-light text-muted")">
                @if (isCompleted)
                {
                    <span>✓</span>
                }
                else
                {
                    <span>@(step + 1)</span>
                }
            </div>
            <small class="step-label @(isFuture ? "text-muted" : isCurrent ? "fw-bold text-primary" : "text-success")">
                @StepNames[step]
            </small>
        </div>
    }
</div>

@code {
    [Parameter] public int CurrentStep { get; set; }
    [Parameter] public HashSet<int> CompletedSteps { get; set; } = new();
    [Parameter] public List<string> StepNames { get; set; } = new();
    [Parameter] public EventCallback<int> OnStepClicked { get; set; }

    private async Task HandleClick(int step)
    {
        if (CompletedSteps.Contains(step))
        {
            await OnStepClicked.InvokeAsync(step);
        }
    }
}
"}

