                error = "All fields are required for each reference.";
                return;
            }
        }

        await OnNext.InvokeAsync();
    }
}
"}

{"path": "/tmp/sv-9ea731fcb82c44b481bbd613e8db4b09/Components/JobApplication/CoverLetterStep.razor", "file_text": "@namespace sv_9ea731fcb82c44b481bbd613e8db4b09.Components.JobApplication

<h4 class="mb-3">Cover Letter</h4>

<div class="mb-3">
    <textarea class="form-control" rows="10" maxlength="@MaxLength"
              value="@text" @oninput="HandleInput"
              placeholder="Write your cover letter here…"></textarea>
    <div class="form-text text-end">
        @text.Length / @MaxLength characters
    </div>
</div>

<div class="d-flex justify-content-between">
    <button class="btn btn-secondary" @onclick="OnBack">← Back</button>
    <button class="btn btn-primary" @onclick="HandleNext">Next →</button>
</div>

@code {
    [Parameter] public string Text { get; set; } = "";
    [Parameter] public EventCallback<string> TextChanged { get; set; }
    [Parameter] public EventCallback OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private const int MaxLength = 2000;
    private string text = "";

    protected override void OnInitialized()
    {
        text = Text ?? "";
    }

    private async Task HandleInput(ChangeEventArgs e)
    {
        text = e.Value?.ToString() ?? "";
        if (text.Length > MaxLength)
            text = text[..MaxLength];
        await TextChanged.InvokeAsync(text);
    }

    private async Task HandleNext()
    {
        await TextChanged.InvokeAsync(text);
        await OnNext.InvokeAsync();
    }
}
"}

{"path": "/tmp/sv-9ea731fcb82c44b481bbd613e8db4b09/Components/JobApplication/ReviewStep.razor", "file_text": "@namespace sv_9ea731fcb82c44b481bbd613e8db4b09.Components.JobApplication
@using sv_9ea731fcb82c44b481bbd613e8db4b09.Models

<h4 class="mb-3">Review &amp; Submit</h4>

@* Personal Info *@
<div class="card mb-3">
    <div class="card-header d-flex justify-content-between align-items-center">
        <strong>Personal Information</strong>
        <a href="" @onclick="() => OnEditStep.InvokeAsync(0)" @onclick:preventDefault>Edit</a>
    </div>
    <div class="card-body">
        <p><strong>Name:</strong> @Personal.FullName</p>
        <p><strong>Email:</strong> @Personal.Email</p>
        <p><strong>Phone:</strong> @Personal.Phone</p>
        <p class="mb-0"><strong>Address:</strong> @Personal.Address</p>
    </div>
</div>

@* Work History *@
<div class="card mb-3">
    <div class="card-header d-flex justify-content-between align-items-center">
        <strong>Work History</strong>
        <a href="" @onclick="() => OnEditStep.InvokeAsync(1)" @onclick:preventDefault>Edit</a>
    </div>
    <div class="card-body">
        @foreach (var entry in WorkEntries)
        {
            <div class="mb-3 pb-2 border-bottom last-child-no-border">
                <p class="fw-bold mb-1">@entry.Title at @entry.Company</p>
                <p class="text-muted mb-1">
                    @entry.StartDate?.ToString("MMM yyyy") –
                    @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy") ?? "N/A")
