@using sv_9ea731fcb82c44b481bbd613e8db4b09.Models

<div class="card mb-3">
    <div class="card-body">
        <div class="d-flex justify-content-between align-items-center mb-3">
            <h6 class="card-title mb-0">Reference @(Index + 1)</h6>
            @if (CanRemove)
            {
                <button class="btn btn-outline-danger btn-sm" @onclick="OnRemove">Remove</button>
            }
        </div>

        <div class="row mb-2">
            <div class="col-md-6">
                <label class="form-label">Name <span class="text-danger">*</span></label>
                <input type="text" class="form-control" @bind="Reference.Name" @bind:event="oninput" />
            </div>
            <div class="col-md-6">
                <label class="form-label">Relationship <span class="text-danger">*</span></label>
                <input type="text" class="form-control" @bind="Reference.Relationship" @bind:event="oninput" />
            </div>
        </div>

        <div class="row mb-0">
            <div class="col-md-6">
                <label class="form-label">Email <span class="text-danger">*</span></label>
                <input type="email" class="form-control" @bind="Reference.Email" @bind:event="oninput" />
            </div>
            <div class="col-md-6">
                <label class="form-label">Phone <span class="text-danger">*</span></label>
                <input type="tel" class="form-control" @bind="Reference.Phone" @bind:event="oninput" />
            </div>
        </div>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public ReferenceModel Reference { get; set; } = default!;
    [Parameter] public int Index { get; set; }
    [Parameter] public bool CanRemove { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }
}

@namespace sv_9ea731fcb82c44b481bbd613e8db4b09.Components.JobApplication
@using sv_9ea731fcb82c44b481bbd613e8db4b09.Models

<h4 class="mb-3">Personal Information</h4>

<div class="mb-3">
    <label class="form-label">Full Name <span class="text-danger">*</span></label>
    <input type="text" class="form-control @ValidationClass("FullName")"
           @bind="Model.FullName" @bind:event="oninput" />
    @if (errors.ContainsKey("FullName"))
    {
        <div class="invalid-feedback">@errors["FullName"]</div>
    }
</div>

<div class="mb-3">
    <label class="form-label">Email <span class="text-danger">*</span></label>
    <input type="email" class="form-control @ValidationClass("Email")"
           @bind="Model.Email" @bind:event="oninput" />
    @if (errors.ContainsKey("Email"))
    {
        <div class="invalid-feedback">@errors["Email"]</div>
    }
</div>

<div class="mb-3">
    <label class="form-label">Phone <span class="text-danger">*</span></label>
    <input type="tel" class="form-control @ValidationClass("Phone")"
           @bind="Model.Phone" @bind:event="oninput" />
    @if (errors.ContainsKey("Phone"))
    {
        <div class="invalid-feedback">@errors["Phone"]</div>
    }
</div>

<div class="mb-3">
    <label class="form-label">Address <span class="text-danger">*</span></label>
    <textarea class="form-control @ValidationClass("Address")"
              @bind="Model.Address" @bind:event="oninput" rows="2"></textarea>
    @if (errors.ContainsKey("Address"))
    {
        <div class="invalid-feedback">@errors["Address"]</div>
    }
</div>

@if (isValidating)
{
    <div class="text-info mb-3">
        <span class="spinner-border spinner-border-sm"></span> Validating email…
    </div>
}

<div class="d-flex justify-content-end">
    <button class="btn btn-primary" @onclick="HandleNext" disabled="@isValidating">Next →</button>
</div>

@code {
    [Parameter, EditorRequired] public PersonalInfoModel Model { get; set; } = default!;
    [Parameter, EditorRequired] public IApplicationService ApplicationService { get; set; } = default!;
    [Parameter] public EventCallback OnNext { get; set; }

    private Dictionary<string, string> errors = new();
    private bool isValidating;

    private string ValidationClass(string field) =>
        errors.ContainsKey(field) ? "is-invalid" : "";

    private async Task HandleNext()
    {
        errors.Clear();

        if (string.IsNullOrWhiteSpace(Model.FullName))
            errors["FullName"] = "Full name is required.";
        if (string.IsNullOrWhiteSpace(Model.Email))
            errors["Email"] = "Email is required.";
        if (string.IsNullOrWhiteSpace(Model.Phone))
            errors["Phone"] = "Phone number is required.";
        if (string.IsNullOrWhiteSpace(Model.Address))
            errors["Address"] = "Address is required.";

        if (errors.Count > 0) return;

        isValidating = true;
        var isValidEmail = await ApplicationService.ValidateEmailAsync(Model.Email);
        isValidating = false;

        if (!isValidEmail)
        {
            errors["Email"] = "Please enter a valid email address.";
            return;
        }

        await OnNext.InvokeAsync();
    }
}

