@namespace sv_9ea731fcb82c44b481bbd613e8db4b09.Components.JobApplication

<h4 class="mb-3">Cover Letter</h4>

<div class="mb-3">
    <textarea class="form-control" rows="10" maxlength="@MaxLength"
              value="@text" @oninput="HandleInput"
              placeholder="Write your cover letter here…"></textarea>
    <div class="form-text text-end">
        @text.Length / @MaxLength characters
    </div>
</div>

<div class="d-flex justify-content-between">
    <button class="btn btn-secondary" @onclick="OnBack">← Back</button>
    <button class="btn btn-primary" @onclick="HandleNext">Next →</button>
</div>

@code {
    [Parameter] public string Text { get; set; } = "";
    [Parameter] public EventCallback<string> TextChanged { get; set; }
    [Parameter] public EventCallback OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private const int MaxLength = 2000;
    private string text = "";

    protected override void OnInitialized()
    {
        text = Text ?? "";
    }

    private async Task HandleInput(ChangeEventArgs e)
    {
        text = e.Value?.ToString() ?? "";
        if (text.Length > MaxLength)
            text = text[..MaxLength];
        await TextChanged.InvokeAsync(text);
    }

    private async Task HandleNext()
    {
        await TextChanged.InvokeAsync(text);
        await OnNext.InvokeAsync();
    }
}

