@* Personal Info *@
<div class="card mb-3">
    <div class="card-header d-flex justify-content-between align-items-center">
        <strong>Personal Information</strong>
        <a href="" @onclick="() => OnEditStep.InvokeAsync(0)" @onclick:preventDefault>Edit</a>
    </div>
    <div class="card-body">
        <p><strong>Name:</strong> @Personal.FullName</p>
        <p><strong>Email:</strong> @Personal.Email</p>
        <p><strong>Phone:</strong> @Personal.Phone</p>
        <p class="mb-0"><strong>Address:</strong> @Personal.Address</p>
    </div>
</div>

@* Work History *@
<div class="card mb-3">
    <div class="card-header d-flex justify-content-between align-items-center">
        <strong>Work History</strong>
        <a href="" @onclick="() => OnEditStep.InvokeAsync(1)" @onclick:preventDefault>Edit</a>
    </div>
    <div class="card-body">
        @foreach (var entry in WorkEntries)
        {
            <div class="mb-3 pb-2 border-bottom last-child-no-border">
                <p class="fw-bold mb-1">@entry.Title at @entry.Company</p>
                <p class="text-muted mb-1">
                    @entry.StartDate?.ToString("MMM yyyy") –
                    @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy") ?? "N/A")
                </p>
                @if (!string.IsNullOrWhiteSpace(entry.Description))
                {
                    <p class="mb-0">@entry.Description</p>
                }
            </div>
        }
    </div>
</div>

@* References *@
<div class="card mb-3">
    <div class="card-header d-flex justify-content-between align-items-center">
        <strong>References</strong>
        <a href="" @onclick="() => OnEditStep.InvokeAsync(2)" @onclick:preventDefault>Edit</a>
    </div>
    <div class="card-body">
        @foreach (var r in References)
        {
            <div class="mb-2">
                <strong>@r.Name</strong> — @r.Relationship<br />
                <span class="text-muted">@r.Email · @r.Phone</span>
            </div>
        }
    </div>
</div>

@* Cover Letter *@
<div class="card mb-3">
    <div class="card-header d-flex justify-content-between align-items-center">
        <strong>Cover Letter</strong>
        <a href="" @onclick="() => OnEditStep.InvokeAsync(3)" @onclick:preventDefault>Edit</a>
    </div>
    <div class="card-body">
        <p class="mb-0" style="white-space: pre-wrap;">@(string.IsNullOrWhiteSpace(CoverLetter) ? "(none)" : CoverLetter)</p>
    </div>
</div>

<div class="d-flex justify-content-between">
    <button class="btn btn-secondary" @onclick="OnBack">← Back</button>
    <button class="btn btn-success btn-lg" @onclick="HandleSubmit" disabled="@IsSubmitting">
        @if (IsSubmitting)
        {
            <span class="spinner-border spinner-border-sm me-1"></span>
            <span>Submitting…</span>
        }
        else
        {
            <span>Submit Application</span>
        }
    </button>
</div>

@code {
    [Parameter, EditorRequired] public PersonalInfoModel Personal { get; set; } = default!;
    [Parameter, EditorRequired] public List<WorkEntryModel> WorkEntries { get; set; } = default!;
    [Parameter, EditorRequired] public List<ReferenceModel> References { get; set; } = default!;
    [Parameter] public string CoverLetter { get; set; } = "";
    [Parameter] public bool IsSubmitting { get; set; }
    [Parameter] public EventCallback<int> OnEditStep { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }
    [Parameter] public EventCallback OnSubmit { get; set; }

    private async Task HandleSubmit()
    {
        await OnSubmit.InvokeAsync();
    }
}

@page "/apply"
@using sv_9ea731fcb82c44b481bbd613e8db4b09.Components.JobApplication
@using sv_9ea731fcb82c44b481bbd613e8db4b09.Models
@rendermode InteractiveServer
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="container py-4" style="max-width: 800px;">
    <h2 class="mb-4">Job Application</h2>

    @if (isSubmitted)
    {
        <div class="alert alert-success text-center py-5">
            <h3 class="mb-3">🎉 Application Submitted!</h3>
            <p class="fs-5">Your application ID is: <strong>@applicationId</strong></p>
            <p class="text-muted">Thank you for applying. We will review your application and get back to you.</p>
        </div>
    }
    else
    {
        <StepIndicator CurrentStep="currentStep"
                       CompletedSteps="completedSteps"
                       StepNames="stepNames"
                       OnStepClicked="GoToStep" />

        <div class="mt-4">
            @switch (currentStep)
            {
                case 0:
                    <PersonalInfoStep Model="personalInfo"
                                      ApplicationService="ApplicationService"
                                      OnNext="NextStep" />
                    break;
                case 1:
                    <WorkHistoryStep Entries="workEntries"
                                     OnNext="NextStep"
                                     OnBack="PreviousStep" />
                    break;
                case 2:
                    <ReferencesStep References="references"
                                    OnNext="NextStep"
                                    OnBack="PreviousStep" />
                    break;
                case 3:
                    <CoverLetterStep @bind-Text="coverLetter"
                                     OnNext="NextStep"
                                     OnBack="PreviousStep" />
                    break;
                case 4:
                    <ReviewStep Personal="personalInfo"
                                WorkEntries="workEntries"
                                References="references"
                                CoverLetter="@coverLetter"
                                IsSubmitting="isSubmitting"
                                OnEditStep="GoToStep"
                                OnBack="PreviousStep"
                                OnSubmit="HandleSubmit" />
                    break;
            }
        </div>
    }
</div>

@code {
    private int currentStep;
    private HashSet<int> completedSteps = new();
    private bool isSubmitted;
    private bool isSubmitting;
    private int applicationId;

    private PersonalInfoModel personalInfo = new();
    private List<WorkEntryModel> workEntries = new() { new() };
    private List<ReferenceModel> references = new() { new(), new() };
    private string coverLetter = "";

    private readonly List<string> stepNames =
    [
        "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit"
    ];

    private void NextStep()
    {
        completedSteps.Add(currentStep);
        currentStep++;
    }

    private void PreviousStep()
    {
        currentStep--;
    }

    private void GoToStep(int step)
    {
        currentStep = step;
    }

    private async Task HandleSubmit()
    {
        isSubmitting = true;

        var application = new JobApplication(
            new PersonalInfo(personalInfo.FullName, personalInfo.Email, personalInfo.Phone, personalInfo.Address),
            new WorkHistory(workEntries.Select(e => new WorkEntry(
                e.Company, e.Title, e.StartDate!.Value, e.IsCurrent ? null : e.EndDate, e.Description
            )).ToList()),
            references.Select(r => new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList(),
            coverLetter
        );

        applicationId = await ApplicationService.SubmitApplicationAsync(application);
        isSubmitting = false;
        isSubmitted = true;
    }
}

